def read(p,d=None):return json.loads(p.read_text()) if p.exists() else d
def num(x,n=3):return 'null' if x is None else f'{x:.{n}f}'
def scaled(x,k):return None if x is None else x*k
def normalize(e):return [e.tag,sorted(e.attrib.items()),(e.text or '').strip(),[normalize(x) for x in e]]
lock=read(COMMON/'goals.locked.json');rows=read(RUN/'campaign/metrics.json',[]);audit=[]
