 p=Path(r['run_directory']);g=lock['goals'][r['goal_index']];a=ET.parse(p/'world.sdf').getroot();b=ET.fromstring((COMMON/g['world']).read_text().replace('fixture://',str(COMMON/'fixture')+'/'))
